fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // Initialize search bounds to cover the entire array
    let mut left = 0;
    let mut right = v.len() - 1;

    // Since the array is sorted and target is guaranteed to be present,
    // we continue until we find an index where v[index] == k.
    // The loop invariant:
    // - left and right are within bounds of v
    // - v[left] <= k <= v[right], so the target is always within [left, right]
    while left < right {
        // mid biased towards left to ensure progress
        let mid = left + (right - left) / 2;

        if v[mid] < k {
            // Target must be to right of mid, so adjust left boundary
            left = mid + 1;
        } else {
            // v[mid] >= k, so target is at mid or to the left
            right = mid;
        }
    }

    // At this point left == right, and v[left] == k (guaranteed by problem statement)
    left
}